const lead = $('Get Lead + Brain').first().json;
const history = $('Get Conversation History').all().map(i => i.json).reverse();
const userMessage = $('Extract Data').first().json.message;

const systemPrompt = lead.system_prompt || `You are an expert sales agent for ${lead.brand_name || 'ABM Groups'}. Your job is to qualify leads and guide them towards enrollment/purchase.

Product Info:
${lead.product_info || 'Premium courses and services'}

Pricing:
${lead.pricing_info || 'Contact for pricing'}

Handling Objections:
${lead.objections_info || 'Address concerns empathetically'}

Rules:
- Keep replies short (2-4 lines max)
- Use emojis sparingly
- Always end with a question to keep conversation going
- If lead score should increase, mention it
- Guide towards: call booking or payment
- Reply in the same language as the lead
- Never make up prices not in your knowledge`;

const messages = [
  { role: 'system', content: systemPrompt }
];

for (const h of history) {
  messages.push({
    role: h.direction === 'inbound' ? 'user' : 'assistant',
    content: h.message
  });
}

messages.push({ role: 'user', content: userMessage });

return [{ json: { messages, lead, userMessage } }];

const aiResponse = $json.choices[0].message.content;
const lead = $('Build AI Prompt').first().json.lead;

let newScore = parseInt(lead.score) || 0;
let newStatus = lead.status;

const msgLower = $('Extract Data').first().json.message.toLowerCase();

// Score logic
if (msgLower.includes('yes') || msgLower.includes('interested') || msgLower.includes('want')) newScore = Math.min(newScore + 15, 100);
if (msgLower.includes('price') || msgLower.includes('cost') || msgLower.includes('fee')) newScore = Math.min(newScore + 10, 100);
if (msgLower.includes('call') || msgLower.includes('talk') || msgLower.includes('speak')) newScore = Math.min(newScore + 20, 100);
if (msgLower.includes('pay') || msgLower.includes('enroll') || msgLower.includes('join')) newScore = Math.min(newScore + 25, 100);
if (msgLower.includes('no') || msgLower.includes('not interested') || msgLower.includes('stop')) newScore = Math.max(newScore - 10, 0);

// Status logic
if (newScore >= 80) newStatus = 'hot';
else if (newScore >= 50) newStatus = 'warm';
else if (newScore >= 20) newStatus = 'new';
else newStatus = 'cold';

return [{ json: { aiResponse, lead, newScore, newStatus } }];
